    bg_color = grid[0][0]
    visited = [[False] * cols for _ in range(rows)]
    from collections import deque

    def bfs(r, c, color):
        region = []
        q = deque([(r, c)])
        visited[r][c] = True
        region.append((r, c))
        while q:
            cr, cc = q.popleft()
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc] == color:
                    visited[nr][nc] = True
                    region.append((nr, nc))
                    q.append((nr, nc))
        return region

    for r in range(rows):
        for c in range(cols):
            color = grid[r][c]
            if color == bg_color or visited[r][c]:
                continue

            region = bfs(r, c, color)
            if not region:
                continue

            min_r, max_r = min(p[0] for p in region), max(p[0] for p in region)
            min_c, max_c = min(p[1] for p in region), max(p[1] for p in region)

            valid = True

            # Check top and bottom rows are all frame color
            for k in range(min_c, max_c + 1):
                if grid[min_r][k] != color or grid[max_r][k] != color:
