def transform(grid):
    from collections import Counter
    if not grid:
        return grid

    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    if cols == 0:
        return grid

    counts = Counter()
    for r in range(rows):
        for c in range(cols):
            counts[grid[r][c]] += 1
    bg = counts.most_common(1)[0][0]

    updates = []
    diag_dirs = [(-1, -1), (-1, 1), (1, -1), (1, 1)]

    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val == bg:
                continue

            for dr, dc in diag_dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == val:
                    rr, cc = nr + dr, nc + dc
                    while 0 <= rr < rows and 0 <= cc < cols:
                        if grid[rr][cc] == bg:
                            updates.append((rr, cc, val))
                            rr += dr
                            cc += dc
                        else:
                            break

                    rr, cc = r - dr, c - dc
                    while 0 <= rr < rows and 0 <= cc < cols:
                        if grid[rr][cc] == bg:
                            updates.append((rr, cc, val))
                            rr -= dr
                            cc -= dc
                        else:
                            break

    result = [row[:] for row in grid]
    for r, c, v in updates:
        if result[r][c] == bg:
            result[r][c] = v

    return result

import collections

def transform(grid):
    rows = len(grid)
    cols = len(grid[0])

    # Identify the dominant color as the background
    counts = collections.Counter()
    for r in range(rows):
        for c in range(cols):
            counts[grid[r][c]] += 1

    bg_color = max(counts.items(), key=lambda x: x[1])[0]

    # Fill color derived from the demonstration output
    fill_color = 4

    visited = [[False] * cols for _ in range(rows)]
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == bg_color and not visited[r][c]:
                visited[r][c] = True
                component = []
                queue = [(r, c)]

                is_boundary = False
                if r == 0 or r == rows - 1 or c == 0 or c == cols - 1:
                    is_boundary = True

                idx = 0
                while idx < len(queue):
                    cr, cc = queue[idx]
                    idx += 1
                    component.append((cr, cc))

                    for dr, dc in dirs:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if not visited[nr][nc] and grid[nr][nc] == bg_color:
                                visited[nr][nc] = True
                                queue.append((nr, nc))
                                if nr == 0 or nr == rows - 1 or nc == 0 or nc == cols - 1:
                                    is_boundary = True

                # If the component does not touch the grid boundary, it is enclosed
                if not is_boundary:
                    for rr, cc in component:
                        grid[rr][cc] = fill_color

    return grid

