def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # Count all colors to find the most frequent (background)
    color_counts = {}
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            color_counts[val] = color_counts.get(val, 0) + 1

    background = max(color_counts.items(), key=lambda x: x[1])[0]

    # Find all background cells reachable from grid boundary
    visited = [[False] * cols for _ in range(rows)]
    queue = deque()

    # Add boundary background cells
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == background and (r == 0 or r == rows - 1 or c == 0 or c == cols - 1):
                visited[r][c] = True
                queue.append((r, c))

    # BFS
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    while queue:
        r, c = queue.popleft()
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if not visited[nr][nc] and grid[nr][nc] == background:
                    visited[nr][nc] = True
                    queue.append((nr, nc))

    # Build result - fill unvisited background cells with 4
    result = []
    for r in range(rows):
        result.append([])
        for c in range(cols):
            if grid[r][c] == background and not visited[r][c]:
                result[-1].append(4)
            else:
                result[-1].append(grid[r][c])

    return result

def transform(grid):
    from collections import Counter

    # Count occurrences of each color to determine the background color
    counts = Counter()
    for row in grid:
        for cell in row:
            counts[cell] = counts.get(cell, 0) + 1

    # Get the most frequent color (background)
    grid_background = max(counts, key=counts.get)

    result = []
    for row in grid:
        # Check if the row is uniform (contains only one unique color)
        if len(set(row)) <= 1:
            # Uniform rows stay the same
            result.append(list(row))
        else:
            # In mixed rows, replace the background color with 1
            # This rule is derived from the demo where background color (4) became 1
            result.append([1 if cell == grid_background else cell for cell in row])

    return result

def transform(grid):
    from collections import Counter

    counts = Counter()
    for row in grid:
        for cell in row:
            counts[cell] += 1

    # Background is the most frequent color
    grid_background = max(counts, key=counts.get)

    result = []
    for row in grid:
        num_bg = row.count(grid_background)

        # If uniform (all same color), it stays the same
        if num_bg == len(row):
            result.append(list(row))
        else:
            # Mixed row: Find trailing background segment and replace with 1
            r = list(row)
            suffix_len = 0
            for i in range(len(r) - 1, -1, -1):
                if r[i] == grid_background:
                    suffix_len += 1
                else:
                    break

            for i in range(len(r) - suffix_len, len(r)):
                r[i] = 1
            result.append(r)

    return result

