def transform(grid):
    from collections import Counter

    # Find background color (most frequent)
    counts = Counter()
    for row in grid:
        for cell in row:
            counts[cell] += 1
    bg = max(counts, key=counts.get)

    result = []
    for row in grid:
        r = list(row)

        # Calculate trailing background length
        suffix_len = 0
        for i in range(len(r) - 1, -1, -1):
            if r[i] == bg:
                suffix_len += 1
            else:
                break

        # If row doesn't end with background or is uniform, no change
        if suffix_len == 0 or len(set(r)) == 1:
            result.append(r)
            continue

        # Count non-background blocks
        nb_blocks = 0
        in_nb = False
        for cell in r:
            if cell != bg:
                if not in_nb:
                    nb_blocks += 1
                    in_nb = True
            else:
                in_nb = False

        starts_with_bg = r[0] == bg

        # Change if: starts with BG OR has exactly 1 non-bg block
        if starts_with_bg or nb_blocks == 1:
            for i in range(len(r) - suffix_len, len(r)):
                r[i] = 1
            result.append(r)
        else:
            result.append(r)

    return result

def transform(grid):
    from collections import Counter

    # Determine background color (most frequent)
    counts = Counter()
    for row in grid:
        for cell in row:
            counts[cell] += 1
    bg_color = max(counts, key=counts.get)

    R, C = len(grid), len(grid[0])

    # Find 4-connected components for each color
    visited = [[False] * C for _ in range(R)]
    components = {}  # color -> list of (r, c) tuples for each component

    for r in range(R):
        for c in range(C):
            if grid[r][c] != bg_color and not visited[r][c]:
                color = grid[r][c]
                if color not in components:
                    components[color] = []
                q = [(r, c)]
                comp_all = [(r, c)]
                visited[r][c] = True

                idx = 0
                while idx < len(comp_all):
                    cr, cc = comp_all[idx]
                    idx += 1

                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < R and 0 <= nc < C:
                            if not visited[nr][nc] and grid[nr][nc] == color:
                                visited[nr][nc] = True
                                comp_all.append((nr, nc))
                                q.append((nr, nc))

                if len(comp_all) >= 3:  # Minimum size threshold
                    components.setdefault(color, []).append(comp_all)

    # Build result with background only
    result = [[bg_color for _ in range(C)] for _ in range(R)]

    density_threshold = 0.5

    # For each component, check if it's substantial enough to fill
    for color, component_list in components.items():
        for cells in component_list:
            rows = [r for r, c in cells]
            cols = [c for r, c in cells]
            min_r, max_r = min(rows), max(rows)
            min_c, max_c = min(cols), max(cols)

            bbox_area = (max_r - min_r + 1) * (max_c - min_c + 1)
            cell_count = len(cells)

            # Fill if density >= 50% and min size
            if bbox_area > 0 and cell_count >= bbox_area * density_threshold and cell_count >= 3:
