                        elif tile[tr][tc] != val:
                            is_consistent = False
                            break
                    if not is_consistent:
                        break

                if not is_consistent:
                    continue

                # Check if we successfully filled the tile
                # and if the mask color 'm' is not part of the tile pattern
                # (Assuming 'm' represents missing values/hole filling)
                full = True
                has_mask = False
                for row in tile:
                    if None in row:
